struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t sz;
    size_t head; /* index of oldest byte */
    size_t tail; /* index where next write goes */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb = NULL;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = malloc(capacity);
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->sz = 0;
    rb->head = 0;
    rb->tail = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t n;

    if (!rb || !data || len == 0)
        return 0;

    n = rb->capacity - rb->sz;
    if (n > len)
        n = len;

    /* first segment: from tail to end of buffer */
